415	std::vector<PhysicsBBQueryResult> PhysicsWorldQuery::queryBoundingBox(const Rect& rect, unsigned int categoryMask)
416	{
417	    std::vector<PhysicsBBQueryResult> results;
418	
419	    if (!_initialized || _space == nullptr)
420	    {
421	        return results;
422	    }
423	
424	    std::vector<PhysicsShape*> shapes;
425	    cpSpaceBBQuery(_space,
426	                   PhysicsHelper::rect2cpbb(rect),
427	                   makeCategoryFilter(categoryMask),
428	                   collectShape,
429	                   &shapes);
430	
431	    results.reserve(shapes.size());
432	    for (auto shape : shapes)
433	    {
434	        PhysicsBBQueryResult entry = { shape };
435	        results.push_back(entry);
436	    }
437	
438	    return results;
439	}
