441	std::vector<PhysicsNearestResult> PhysicsWorldQuery::queryPointAll(const Vec2& point, float maxDistance, unsigned int categoryMask)
442	{
443	    std::vector<PhysicsNearestResult> results;
444	
445	    if (!_initialized || _space == nullptr)
446	    {
447	        return results;
448	    }
449	
450	    cpSpacePointQuery(_space,
451	                      PhysicsHelper::point2cpv(point),
452	                      maxDistance,
453	                      makeCategoryFilter(categoryMask),
454	                      collectPointHit,
455	                      &results);
456	
457	    // Closest first; a stable sort leaves equal distances in the order they were collected.
458	    std::stable_sort(results.begin(), results.end(),
459	                     [](const PhysicsNearestResult& a, const PhysicsNearestResult& b) {
460	                         return a.distance < b.distance;
461	                     });
462	
463	    return results;
464	}
