528	std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesAlongRay(const Vec2& start, const Vec2& end, unsigned int categoryMask)
529	{
530	    std::vector<PhysicsBody*> bodies;
531	
532	    // The hits arrive sorted by alpha, so first occurrence order is distance order.
533	    std::vector<PhysicsSegmentQueryResult> hits = querySegment(start, end, 0.0f, categoryMask);
534	    bodies.reserve(hits.size());
535	
536	    for (const auto& hit : hits)
537	    {
538	        PhysicsBody* body = hit.shape == nullptr ? nullptr : hit.shape->getBody();
539	        if (body != nullptr)
540	        {
541	            appendUnique(bodies, body);
542	        }
543	    }
544	
545	    return bodies;
546	}
