564	std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesInCircle(const Vec2& center, float radius, unsigned int categoryMask)
565	{
566	    std::vector<PhysicsBody*> bodies;
567	
568	    if (!_initialized || _space == nullptr || radius < 0.0f)
569	    {
570	        return bodies;
571	    }
572	
573	    CircleCollector collector;
574	    collector.center = PhysicsHelper::point2cpv(center);
575	    collector.radius = radius;
576	
577	    cpSpaceBBQuery(_space,
578	                   cpBBNewForExtents(collector.center, radius, radius),
579	                   makeCategoryFilter(categoryMask),
580	                   collectCircleShape,
581	                   &collector);
