598	bool PhysicsWorldQuery::lineOfSight(const Vec2& start, const Vec2& end, unsigned int blockMask)
599	{
600	    // An uninitialised facade cannot see anything, so it cannot affirm a clear line either.
601	    if (!_initialized || _space == nullptr)
602	    {
603	        return false;
604	    }
605	
606	    if (start == end)
607	    {
608	        return true;
609	    }
610	
611	    // Only a shape strictly between the endpoints blocks: a shape touching start or end
612	    // (the observer's own body, or the target itself) leaves the sight line intact.
613	    std::vector<PhysicsSegmentQueryResult> hits = querySegment(start, end, 0.0f, blockMask);
614	    for (const auto& hit : hits)
615	    {
616	        if (hit.alpha > kAlphaEpsilon && hit.alpha < 1.0f - kAlphaEpsilon)
617	        {
618	            return false;
