669	std::vector<Vec2> PhysicsWorldQuery::findOpenPositions(const Rect& searchArea, float spacing, float clearance, unsigned int blockMask)
670	{
671	    std::vector<Vec2> positions;
672	
673	    if (!_initialized || _space == nullptr || spacing <= 0.0f)
674	    {
675	        return positions;
676	    }
677	
678	    int columns = static_cast<int>(std::floor(searchArea.size.width / spacing)) + 1;
679	    int rows = static_cast<int>(std::floor(searchArea.size.height / spacing)) + 1;
680	
681	    if (columns <= 0 || rows <= 0)
682	    {
683	        return positions;
684	    }
685	
686	    columns = std::min(columns, kMaxGridSamplesPerAxis);
687	    rows = std::min(rows, kMaxGridSamplesPerAxis);
688	
689	    const cpShapeFilter filter = makeCategoryFilter(blockMask);
690	    const float reach = clearance > 0.0f ? clearance : 0.0f;
691	    const float originX = searchArea.getMinX();
692	    const float originY = searchArea.getMinY();
693	
694	    // Row major: bottom row first, left to right within each row.
695	    for (int row = 0; row < rows; ++row)
696	    {
697	        const float y = originY + spacing * static_cast<float>(row);
698	
699	        for (int column = 0; column < columns; ++column)
700	        {
701	            const float x = originX + spacing * static_cast<float>(column);
702	
703	            // No blocking shape within reach means the sample is farther than the clearance.
704	            if (cpSpacePointQueryNearest(_space, cpv(x, y), reach, filter, nullptr) == nullptr)
705	            {
706	                positions.push_back(Vec2(x, y));
707	            }
708	        }
709	    }
710	
711	    return positions;
712	}
