440	bool PhysicsRayCast::lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask)
441	{
442	    if (!_initialized)
443	    {
444	        return false;
445	    }
446	
447	    cpSpace* space = activeSpace(_world, _space);
448	    if (space == nullptr)
449	    {
450	        // No space to query means there is nothing that could block the segment.
451	        return true;
452	    }
453	
454	    Vec2 delta = to - from;
455	    Vec2 direction;
456	    float length = 0.0f;
457	    if (!prepareRay(delta, delta.length(), _maxDistance, &direction, &length))
458	    {
459	        // Both ends coincide, so the target is trivially visible.
460	        return true;
461	    }
462	
463	    cpShapeFilter filter = buildFilter(_defaultCategoryMask,
464	                                       obstacleMask != 0 ? obstacleMask : _defaultCollisionMask,
465	                                       _defaultGroup);
466	
467	    return !segmentFirstHit(space, from, direction, length, filter, nullptr);
468	}
