475	    }
476	
477	    Vec2 rayDirection;
478	    float length = 0.0f;
479	    if (!prepareRay(direction, maxDist, _maxDistance, &rayDirection, &length))
480	    {
481	        return RAYCAST_NO_HIT_DISTANCE;
482	    }
483	
484	    cpSpace* space = activeSpace(_world, _space);
485	    if (space == nullptr)
486	    {
487	        return RAYCAST_NO_HIT_DISTANCE;
